-- 知识文件类型字典
INSERT IGNORE INTO `system_dict_type` VALUES (103, '文件类型', 'kmc_file_type', '0', '吴同', '2026-07-15 10:20:21', '吴同', '2026-07-15 10:21:24', '知识库文档文件类型');
INSERT IGNORE INTO `system_dict_data` VALUES (187, 1, '非结构化文件', 'text', 'kmc_file_type', NULL, 'primary', 'N', '0', '吴同', '2026-07-15 10:21:39', '吴同', '2026-07-15 10:32:33', NULL);
INSERT IGNORE INTO `system_dict_data` VALUES (188, 2, '半结构化文件', 'json', 'kmc_file_type', NULL, 'info', 'N', '0', '吴同', '2026-07-15 10:21:55', '吴同', '2026-07-15 10:32:40', NULL);

-- 知识库知识文件增加文件类型和 JSON 数据风格
ALTER TABLE `kmc_document`
    ADD COLUMN `file_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件类型;text：普通文件，json：JSON文件' AFTER `segment_num`,
    ADD COLUMN `json_style` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT 'json 风格' AFTER `file_type`;
UPDATE `kmc_document` SET `file_type` = 'text' ;

-- 知识图谱知识文件仅增加文件类型，不保存 JSON 数据风格
ALTER TABLE `kg_knowledge_document`
    ADD COLUMN `file_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT 'text' COMMENT '文件类型;text：普通文件，json：JSON文件' AFTER `description`;


